import numpy as np,json
L=open("start.xyz").read().split("\n"); n=int(L[0])
s=[];P=[]
for l in L[2:2+n]:
    t=l.split(); s.append(t[0]); P.append(list(map(float,t[1:4])))
P=np.array(P); meta=json.load(open("idx.json")); frag=meta["frag"]
rad={'H':1.2,'C':1.75,'N':1.6,'Ir':2.0}
out=[]
for i in range(n):
    for j in range(i+1,n):
        if frag[i]==frag[j]: continue
        r=2.7 if (s[i]=='Ir' or s[j]=='Ir') else rad[s[i]]+rad[s[j]]
        d=np.linalg.norm(P[i]-P[j])
        if d<r: out.append((round(r-d,2),s[i],i,s[j],j,round(d,2),frag[i],frag[j]))
out.sort(reverse=True)
for o in out[:20]: print(o)
