rad={'H':1.2,'C':1.75,'N':1.6,'Ir':2.0}
def pen(syms,P,frag):
    n=len(syms); D=np.linalg.norm(P[:,None]-P[None],axis=-1); t=0
    for i in range(n):
        for j in range(i+1,n):
            if frag[i]==frag[j]: continue
            ir = (syms[i]=='Ir' or syms[j]=='Ir')
            r=3.0 if ir else rad[syms[i]]+rad[syms[j]]
            if D[i,j]<r: t+= (5.0 if ir else 1.0)*(r-D[i,j])**2
    return t
